const a="b15d84c82f7d",e="vertaler + keurder (claude-opus-5-5)",n="2026-10-20",l=[{personId:"B",after:[],nudge:"Empieza por Bruno. Se encontraba justo al lado de una mesa. Busca la mesa y mira qué casillas libres tiene al lado.",reasoning:"La mesa está en la fila 4, columna 4. A su izquierda, en la fila 4, columna 3, hay una estantería, y ahí no puede estar nadie. Solo queda una casilla justo al lado de la mesa.",answer:"Bruno está en la fila 3, columna 4, justo encima de la mesa. En la otra casilla justo al lado de la mesa hay una estantería."},{personId:"A",after:["B"],nudge:"Fíjate en Ana. Estaba en la 2.ª columna. ¿Qué casillas de la columna 2 siguen siendo posibles?",reasoning:"En la fila 1, columna 2 hay un armario y en la fila 4, columna 2 una estantería: ahí no puede estar nadie. Cada fila tiene exactamente una persona, y la fila 3 ya está ocupada por Bruno. Queda una sola casilla en la columna 2.",answer:"Ana está en la fila 2, columna 2. En la columna 2 hay un armario (fila 1) y una estantería (fila 4), y la fila 3 está ocupada por Bruno."},{personId:"C",after:["B","A"],nudge:"Fíjate en Cristina. Se encontraba ante una ventana. Busca las ventanas en el plano.",reasoning:"Hay ventanas en tres casillas: fila 1, columna 3; fila 3, columna 1; y fila 4, columna 4. En la fila 4, columna 4 hay una mesa, y la fila 3 ya está ocupada por Bruno. ¿Qué ventana queda?",answer:"Cristina está en la fila 1, columna 3, ante la ventana de arriba. La ventana de la fila 3 queda descartada por Bruno, y en la casilla de la ventana de la fila 4 hay una mesa."},{personId:"V",after:["B","A","C"],nudge:"Valeria es la víctima y no tiene tarjeta. Mira qué fila y qué columna siguen vacías.",reasoning:"Cada fila y cada columna tiene exactamente una persona. Bruno, Ana y Cristina ya están en las filas 3, 2 y 1, y en las columnas 4, 2 y 3. Solo la fila 4 y la columna 1 siguen vacías.",answer:"Valeria está en la fila 4, columna 1. Es la única fila y la única columna donde todavía no hay nadie."}],s="Valeria estaba en la bodega. Bruno es el único sospechoso que estaba allí (Ana y Cristina estaban en el despacho), así que Bruno es el culpable.",o={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},i={source:a,model:e,date:n,steps:l,murderer:s,review:o},r="850dbab4bf0c",u="vertaler (claude-opus-5-5)",t="2026-10-20",c=[{personId:"C",after:[],nudge:"Empieza por Cristina. Estaba en la fila inferior. ¿Qué casillas de la fila 4 están libres?",reasoning:"La fila inferior es la fila 4. En las columnas 2, 3 y 4 de esa fila hay mesas, y ahí no puede estar nadie. Solo queda una casilla.",answer:"Cristina está en la fila 4, columna 1. Las demás casillas de la fila 4 las ocupan mesas."},{personId:"A",after:["C"],nudge:"Fíjate en Adrián. Estaba al pie de una ventana. Busca las ventanas en el plano.",reasoning:"Hay ventanas en tres casillas: fila 1, columna 1; fila 1, columna 3; y fila 4, columna 1. Cada columna tiene exactamente una persona, y la columna 1 ya está ocupada por Cristina. ¿Qué ventana queda?",answer:"Adrián está en la fila 1, columna 3, al pie de la ventana de arriba. Las otras ventanas están en la columna 1, y esa columna está ocupada por Cristina."},{personId:"B",after:["C","A"],nudge:"Fíjate en Bárbara. Se encontraba en la 2.ª columna. ¿Qué casillas de la columna 2 siguen siendo posibles?",reasoning:"La fila 1 está ocupada por Adrián y la fila 4 por Cristina. En la fila 2, columna 2 hay un armario, y ahí no puede estar nadie. Queda una sola casilla en la columna 2.",answer:"Bárbara está en la fila 3, columna 2. La fila 1 y la fila 4 están ocupadas, y en la fila 2, columna 2 hay un armario."},{personId:"V",after:["C","A","B"],nudge:"Venancio es la víctima y no tiene tarjeta. Mira qué fila y qué columna siguen vacías.",reasoning:"Cada fila y cada columna tiene exactamente una persona. Cristina, Adrián y Bárbara ya están en las filas 4, 1 y 3, y en las columnas 1, 3 y 2. Solo la fila 2 y la columna 4 siguen vacías.",answer:"Venancio está en la fila 2, columna 4. Es la única fila y la única columna donde todavía no hay nadie."}],d="Venancio estaba en el despacho. Adrián es el único sospechoso que estaba allí (Bárbara y Cristina estaban en la bodega), así que Adrián es el culpable.",m={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},f={source:r,model:u,date:t,steps:c,murderer:d,review:m},p="0e590a513929",y="vertaler + keurder (claude-opus-5-5)",b="2026-10-20",q=[{personId:"C",after:[],nudge:"Empieza por César. Su tarjeta dice que se encontraba en una silla. Busca la silla en el plano.",reasoning:"César se encontraba en una silla. Solo hay una silla, en el despacho. Ahí tiene que estar César.",answer:"César está en la fila 4, columna 1. Ahí está la única silla, y su tarjeta dice que se encontraba en una silla."},{personId:"A",after:["C"],nudge:"Fíjate en Amaia. Estaba en la fila superior. ¿Qué casillas de la fila 1 siguen siendo posibles?",reasoning:"En la fila 1, columna 2 hay un piano y en la fila 1, columna 3 una planta: ahí no puede estar nadie. Cada columna tiene exactamente una persona, y la columna 1 ya está ocupada por César. Queda una sola casilla en la fila 1.",answer:"Amaia está en la fila 1, columna 4. En la fila 1 hay un piano (columna 2) y una planta (columna 3), y la columna 1 está ocupada por César."},{personId:"B",after:["C","A"],nudge:"Fíjate en Belén. Estaba en la 2.ª columna. ¿Qué casillas de la columna 2 siguen siendo posibles?",reasoning:"En las filas 1 y 2 de la columna 2 hay un piano, y ahí no puede estar nadie. La fila 4 ya está ocupada por César. Queda una sola casilla en la columna 2.",answer:"Belén está en la fila 3, columna 2. En la parte de arriba de la columna 2 hay un piano, y la fila 4 está ocupada por César."},{personId:"V",after:["C","A","B"],nudge:"Valerio es la víctima y no tiene tarjeta. Mira qué fila y qué columna siguen vacías.",reasoning:"Cada fila y cada columna tiene exactamente una persona. César, Amaia y Belén ya están en las filas 4, 1 y 3, y en las columnas 1, 4 y 2. Solo la fila 2 y la columna 3 siguen vacías.",answer:"Valerio está en la fila 2, columna 3. Es la única fila y la única columna donde todavía no hay nadie."}],g="Valerio estaba en el tocador. Amaia es la única sospechosa que estaba allí (Belén y César estaban en el despacho), así que Amaia es la culpable.",v={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},A={source:p,model:y,date:b,steps:q,murderer:g,review:v},E="f5f4c3de566b",h="vertaler + keurder (claude-opus-5-5)",C="2026-10-20",B=[{personId:"D",after:[],nudge:"Empieza por Diego. Su tarjeta menciona un objeto. ¿Cuántos objetos de esos hay en el tablero?",reasoning:"Diego se encontraba en una silla. Mira el plano: solo hay una silla, en el despacho. ¿En qué casilla está esa silla?",answer:"Diego está en la fila 5, columna 2. Ahí está la única silla de la casa, y su tarjeta dice que se encontraba en una silla."},{personId:"C",after:["D"],nudge:"Fíjate en Carlos y en los dos armarios. ¿Qué casillas están junto a un armario y cuáles quedan descartadas por las tarjetas de Alicia y Borja?",reasoning:"Carlos estaba junto a un armario, en la misma estancia. Junto al armario del dormitorio están la fila 1, columna 4; la fila 2, columna 5; y la fila 3, columna 4. Junto al armario de la bodega están la fila 4, columna 5; y la fila 5, columna 4. La columna 5 es para Alicia (columna más a la derecha), la fila 3 es para Borja y la fila 5 está ocupada por Diego. ¿Qué casilla queda?",answer:"Carlos está en la fila 1, columna 4. Las demás casillas junto a un armario quedan descartadas: la columna 5 es para Alicia, la fila 3 para Borja y la fila 5 está ocupada por Diego."},{personId:"B",after:["D","C"],nudge:"Borja se encontraba en la 3.ª fila. Recorre las casillas de esa fila: ¿cuáles están bloqueadas o quedan descartadas por su columna?",reasoning:"Borja se encontraba en la fila 3. En la fila 3, columna 3 está el piano, y ahí no puede estar nadie. La columna 2 está ocupada por Diego y la columna 4 por Carlos. La columna 5 es para Alicia, porque ella estaba en la columna más a la derecha. ¿Qué casilla de la fila 3 queda?",answer:"Borja está en la fila 3, columna 1. En la columna 3 está el piano, las columnas 2 y 4 están ocupadas por Diego y Carlos, y la columna 5 es para Alicia."},{personId:"V",after:["D","C","B"],nudge:"Ahora la víctima, Valerio. ¿Qué filas y columnas siguen libres, y qué columna ya es para Alicia?",reasoning:"Las filas 1, 3 y 5 están ocupadas, igual que las columnas 1, 2 y 4. Quedan las filas 2 y 4 y las columnas 3 y 5. La columna 5 es para Alicia, así que Valerio tiene que estar en la columna 3. En la fila 2, columna 3 está el piano. ¿Dónde puede estar entonces Valerio?",answer:"Valerio yace en la fila 4, columna 3. La columna 5 es para Alicia, así que él tiene que estar en la columna 3, y en la fila 2, columna 3 está el piano."},{personId:"A",after:["D","C","B","V"],nudge:"Alicia es la última que aún no está en el tablero. ¿Qué dice su tarjeta y qué fila sigue libre?",reasoning:"Alicia estaba en la columna más a la derecha, es decir, en la columna 5. Las filas 1, 3, 4 y 5 ya están ocupadas. ¿Qué casilla de la columna 5 queda entonces?",answer:"Alicia está en la fila 2, columna 5. Según su tarjeta estaba en la columna más a la derecha, y las filas 1, 3, 4 y 5 ya están ocupadas."}],D="Valerio yace en el despacho, y Diego es el único sospechoso que también estaba en el despacho. Así que Diego es el culpable.",j={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},L={source:E,model:h,date:C,steps:B,murderer:D,review:j},Q="144a6a6f16d9",w="vertaler + keurder (claude-opus-5-5)",V="2026-10-20",F=[{personId:"B",after:[],nudge:"Empieza por Benito, en la fila superior. ¿Qué casillas están bloqueadas allí y qué dice la tarjeta de Adrián sobre la bodega?",reasoning:"Benito se encontraba en la fila 1. En la fila 1, columna 1 hay un armario, y ahí no puede estar nadie. Las columnas 3, 4 y 5 de la fila 1 pertenecen a la bodega, y Adrián era la única persona en la bodega. Así que Benito no puede estar allí. ¿Qué casilla de la fila 1 queda?",answer:"Benito está en la fila 1, columna 2. En la columna 1 hay un armario, y las columnas 3 a 5 pertenecen a la bodega, donde solo estaba Adrián."},{personId:"D",after:["B"],nudge:"Fíjate en Diana y en las sillas. ¿Qué casillas están justo al lado de una silla en la misma estancia, fuera de la bodega?",reasoning:"Diana se encontraba justo al lado de una silla, en la misma estancia. Dos sillas están en la bodega, pero allí solo estaba Adrián. Las otras dos están en el invernadero, en la fila 4, columna 2; y en la fila 5, columna 1. Justo al lado de ellas están la fila 3, columna 2; la fila 5, columna 2; y la fila 4, columna 1. La columna 2 está ocupada por Benito. ¿Qué casilla queda?",answer:"Diana está en la fila 4, columna 1, justo al lado de las sillas del invernadero. La bodega es de Adrián, y la fila 3, columna 2 y la fila 5, columna 2 quedan descartadas porque Benito ocupa la columna 2."},{personId:"C",after:["B","D"],nudge:"Cristina estaba en una cama. ¿Cuántas casillas ocupa la cama y qué fila ya está ocupada?",reasoning:"Hay una sola cama, en la biblioteca, que ocupa la columna 5, filas 3 y 4. La fila 4 está ocupada por Diana. ¿En qué casilla de la cama puede estar entonces Cristina?",answer:"Cristina está en la fila 3, columna 5. La cama ocupa las filas 3 y 4 de la columna 5, y la fila 4 está ocupada por Diana."},{personId:"V",after:["B","D","C"],nudge:"Ahora la víctima, Victoria. ¿Qué filas siguen libres y en cuál de ellas tiene que ir Adrián?",reasoning:"Las filas 1, 3 y 4 están ocupadas, así que quedan las filas 2 y 5. Adrián estaba en la bodega, que solo ocupa las filas 1 y 2; la fila 1 es de Benito, así que Adrián va en la fila 2. Entonces Victoria tiene que estar en la fila 5. Las columnas 1, 2 y 5 están ocupadas, y en la fila 5, columna 3 está la mesa. ¿Dónde puede estar entonces Victoria?",answer:"Victoria yace en la fila 5, columna 4. La fila 2 es para Adrián (la bodega), las columnas 1, 2 y 5 están ocupadas, y en la fila 5, columna 3 está la mesa."},{personId:"A",after:["B","D","C","V"],nudge:"Adrián es el último que aún no está en el tablero. ¿Qué dice su tarjeta y qué fila y qué columna siguen libres?",reasoning:"Adrián estaba en la bodega, en la fila 1 o en la 2. La fila 1 está ocupada por Benito. La columna 4 está ocupada por Victoria y la columna 5 por Cristina. ¿Qué casilla de la bodega queda?",answer:"Adrián está en la fila 2, columna 3, en la bodega. La fila 1 está ocupada por Benito, la columna 4 por Victoria y la columna 5 por Cristina."}],z="Victoria yace en la biblioteca, y Cristina es la única sospechosa que también estaba en la biblioteca. Así que Cristina es la culpable.",I={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},$={source:Q,model:w,date:V,steps:F,murderer:z,review:I},_="dfa59a49f03b",x="vertaler (claude-opus-5-5)",G="2026-10-20",S=[{personId:"A",after:[],nudge:"Empieza por Amaia. Busca la estantería en el plano y mira qué casillas junto a ella están libres.",reasoning:"Amaia estaba junto a una estantería. Solo hay una estantería: en la fila 5, columna 3, en el salón. En la fila 4, columna 3 hay una planta, y la fila 5, columna 2 está al otro lado de una pared, en el vestíbulo (y allí también hay una planta). ¿Qué casilla junto a la estantería queda?",answer:"Amaia está en la fila 5, columna 4, junto a la estantería. En la fila 4, columna 3 hay una planta y la fila 5, columna 2 está al otro lado de una pared, en el vestíbulo."},{personId:"C",after:["A"],nudge:"Ahora Carlos, en la fila 4. Compara su tarjeta con la de Bruno y fíjate también en Amaia.",reasoning:"Carlos se encontraba en la fila 4. Las columnas 1 y 2 de la fila 4 pertenecen al vestíbulo, y Bruno estaba solo en el vestíbulo, así que Carlos no puede estar allí. En la fila 4, columna 3 hay una planta y la columna 4 está ocupada por Amaia. ¿Qué casilla de la fila 4 queda?",answer:"Carlos está en la fila 4, columna 5. Las columnas 1 y 2 de la fila 4 están en el vestíbulo, donde Bruno estaba solo; en la columna 3 hay una planta y la columna 4 está ocupada por Amaia."},{personId:"D",after:["A","C"],nudge:"Fíjate en Diana y en la columna 2. ¿Qué casillas quedan descartadas por la tarjeta de Bruno?",reasoning:"Diana se encontraba en la columna 2. Las filas 3, 4 y 5 de la columna 2 pertenecen al vestíbulo, donde Bruno estaba solo; Diana no puede estar allí. En la fila 1, columna 2 hay un armario, y ahí no puede estar nadie. ¿Qué casilla de la columna 2 queda entonces?",answer:"Diana está en la fila 2, columna 2. Las filas 3 a 5 de la columna 2 están en el vestíbulo, donde Bruno estaba solo, y en la fila 1, columna 2 hay un armario."},{personId:"B",after:["A","C","D"],nudge:"Bruno estaba en el vestíbulo. ¿Qué filas y columnas del vestíbulo siguen libres?",reasoning:"El vestíbulo ocupa las filas 3, 4 y 5 de las columnas 1 y 2. La fila 4 está ocupada por Carlos, la fila 5 por Amaia y la columna 2 por Diana. ¿Qué casilla del vestíbulo le queda entonces a Bruno?",answer:"Bruno está en la fila 3, columna 1. En el vestíbulo, la fila 4 (Carlos), la fila 5 (Amaia) y la columna 2 (Diana) ya están ocupadas."},{personId:"V",after:["A","C","D","B"],nudge:"Valentín es el último que aún no está en el tablero. ¿Qué fila y qué columna siguen libres?",reasoning:"Todos los sospechosos ya están colocados. La fila 1 es la única fila libre y la columna 3 la única columna libre. ¿Dónde se cruzan?",answer:"Valentín yace en la fila 1, columna 3. La fila 1 y la columna 3 son la única fila y la única columna donde todavía no hay nadie."}],k="Valentín yace en el pasillo. Diana es la única sospechosa en el pasillo, así que Diana es la culpable.",M={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},T={source:_,model:x,date:G,steps:S,murderer:k,review:M},P="74a91d976380",H="vertaler + keurder (claude-opus-5-5)",J="2026-10-20",R=[{personId:"C",after:[],nudge:"Empieza por Cristina. Combina su tarjeta con la de Daniel: ¿qué mujer puede estar en su estancia? Después mira las estancias de la mitad superior.",reasoning:"Cristina es la única mujer, así que, según la tarjeta de Daniel, Cristina está en la misma estancia que Daniel. Cristina está en la mitad superior, pero no en la fila 1: esa fila es para Alberto (según su tarjeta, estaba en la fila superior). En la bodega solo queda entonces la fila 2, y en el salón también, porque allí la fila 3 es una mesa. Cristina y Daniel no caben juntos en una sola fila. En el dormitorio, Bruno, Cristina y Daniel tendrían que estar juntos en las filas 2 y 3, y solo hay dos filas. ¿Qué estancia queda entonces, y qué casilla libre tiene en la mitad superior?",answer:"Cristina está en la fila 3, columna 2. Solo en el tocador caben Cristina y Daniel juntos, y la única casilla libre del tocador en la mitad superior es esta alfombra."},{personId:"A",after:["C"],nudge:"Fíjate en Alberto. Su tarjeta solo deja dos casillas abiertas en la fila superior. ¿Qué columna necesita Daniel en el tocador?",reasoning:"Alberto está en la fila 1 y en la mitad izquierda. La casilla de la columna 2 es una mesa, así que solo quedan la columna 1 y la columna 3. Daniel está con Cristina en el tocador, y el tocador solo tiene las columnas 1 y 2. La columna 2 ya es de Cristina, así que Daniel necesita la columna 1. ¿Qué casilla le queda entonces a Alberto?",answer:"Alberto está en la fila 1, columna 3. La columna 1 hace falta para Daniel en el tocador, y en la fila 1 la columna 2 es una mesa."},{personId:"E",after:["C","A"],nudge:'Fíjate en Eduardo y Bruno. El dormitorio solo tiene dos columnas. ¿Qué significa entonces "en algún lugar a la derecha de Bruno" para Eduardo, y en qué fila tiene que estar Bruno?',reasoning:"Bruno está en el dormitorio, en la columna 5 o 6. Eduardo está en algún lugar a la derecha de él, así que Bruno está en la columna 5 y Eduardo en la columna 6. La fila 1 es de Alberto y la fila 3 de Cristina, así que a Bruno solo le queda la fila 2. En la columna 6 quedan entonces descartadas para Eduardo las filas 1, 2 y 3, y en las filas 4 y 5 hay una mesa. ¿Dónde puede estar todavía Eduardo?",answer:"Eduardo está en la fila 6, columna 6. Tiene que estar en la columna 6; la fila 1 es para Alberto, la fila 2 para Bruno, la fila 3 para Cristina y en las filas 4 y 5 hay una mesa."},{personId:"B",after:["C","A","E"],nudge:"Según su tarjeta, Bruno se encontraba en el dormitorio. Tacha allí las filas y columnas que ya están ocupadas.",reasoning:"El dormitorio ocupa de la fila 1 a la 3 en las columnas 5 y 6. La fila 1 es de Alberto, la fila 3 de Cristina y la columna 6 de Eduardo. ¿Qué casilla queda libre en el dormitorio?",answer:"Bruno está en la fila 2, columna 5. En el dormitorio, la fila 1, la fila 3 y la columna 6 ya están ocupadas."},{personId:"V",after:["C","A","E","B"],nudge:"Ahora Valerio. Mira qué filas y columnas quedan libres, y qué columna necesita ya Daniel.",reasoning:"Quedan libres las filas 4 y 5, y las columnas 1 y 4. Daniel está con Cristina en el tocador, en la columna 1 (la columna 2 es de Cristina). Por tanto, Valerio tiene que estar en la columna 4. Allí, en la fila 5, está la estantería. ¿Qué casilla queda?",answer:"Valerio está en la fila 4, columna 4. La columna 1 es para Daniel, y en la columna 4 la fila 5 es una estantería."},{personId:"D",after:["C","A","E","B","V"],nudge:"Daniel es el último. ¿Qué fila y qué columna quedan completamente libres?",reasoning:"Solo queda una fila libre y una columna libre. ¿Dónde se cruzan? Mira si esa casilla encaja con la tarjeta de Daniel: tiene que estar en la misma estancia que Cristina.",answer:"Daniel está en la fila 5, columna 1. Es la única fila libre y la única columna libre, y la casilla está en el tocador, con Cristina."}],O="Valerio yace en la cocina y Eduardo es el único sospechoso que está allí. Así que Eduardo es el culpable.",U={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},K={source:P,model:H,date:J,steps:R,murderer:O,review:U},N="a6ef3e81331a",W="vertaler (claude-opus-5-5)",X="2026-10-20",Y=[{personId:"E",after:[],nudge:"Empieza por Eduardo: estaba al pie de una ventana. ¿Qué ventanas quedan descartadas por las tarjetas de Amaia y Cristian? Después fíjate en Benito.",reasoning:"La fila 1 es para Amaia y la columna 6 para Cristian, así que de todas las ventanas solo quedan las de la fila 6, columnas 1 y 3: Eduardo estaba en la fila 6, en el vestíbulo. Benito estaba en una esquina, con otro hombre en su estancia: Cristian o Eduardo. Las esquinas del tocador, donde estaba Cristian, están todas en la fila 1, la fila 6 o la columna 6, y esas son para Amaia, Eduardo y Cristian. Así que Benito estaba con Eduardo en el vestíbulo, en una esquina fuera de la fila 6 y fuera de la columna 4 (que es para Débora): la fila 5, columna 1. ¿Qué ventana le queda a Eduardo ahora que la columna 1 es para Benito?",answer:"Eduardo está en la fila 6, columna 3. La fila 1 es para Amaia, la columna 6 para Cristian y la columna 1 para Benito, así que solo queda la ventana de la fila 6, columna 3."},{personId:"B",after:["E"],nudge:"Benito se encontraba en una esquina de su estancia, y en su estancia también había un hombre. ¿Qué hombre puede ser: Cristian o Eduardo?",reasoning:"El otro hombre es Cristian o Eduardo. Cristian estaba en la columna 6, en el tocador; las esquinas del tocador están en la fila 1 (para Amaia), la fila 6 (ocupada por Eduardo) o la columna 6 (para Cristian). Así que Benito estaba con Eduardo en el vestíbulo. El vestíbulo tiene esquinas en la fila 5, columnas 1 y 4, y en la fila 6, columnas 1 y 4. La fila 6 está ocupada y la columna 4 es para Débora: ¿qué esquina queda?",answer:"Benito está en la fila 5, columna 1. Tenía que estar con Eduardo en el vestíbulo, y de las esquinas de allí quedan descartadas la fila 6 (Eduardo) y la columna 4 (Débora)."},{personId:"C",after:["E","B"],nudge:"Cristian estaba en la columna 6 y en algún lugar por encima de Débora. Averigua primero a qué altura puede estar Débora en la columna 4.",reasoning:"Débora estaba en la columna 4. La fila 1 es para Amaia y las filas 5 y 6 están ocupadas, así que le quedan la fila 2, la fila 3 o la fila 4. En la fila 4, columna 4 estaría junto a la estantería de la fila 4, columna 3, y eso no puede ser. Así que Débora está en la fila 2 o en la fila 3. En la columna 6, Cristian todavía tiene libres las filas 2, 3 y 4, pero tiene que estar en algún lugar por encima de Débora. ¿Qué fila encaja entonces?",answer:"Cristian está en la fila 2, columna 6. Débora no puede estar más abajo de la fila 3 (la fila 4 está junto a la estantería), la fila 1 es para Amaia y las filas 5 y 6 están ocupadas."},{personId:"D",after:["E","B","C"],nudge:"Débora estaba en la columna 4. ¿Qué filas quedan libres, y dónde está la estantería?",reasoning:"En la columna 4, la fila 1 es para Amaia y las filas 2, 5 y 6 están ocupadas por Cristian, Benito y Eduardo. Quedan las filas 3 y 4 de la columna 4. Débora no estaba junto a ninguna estantería, y en la fila 4, columna 3 hay una. ¿Qué casilla queda?",answer:"Débora está en la fila 3, columna 4. La fila 1 es para Amaia, las filas 2, 5 y 6 están ocupadas, y la fila 4, columna 4 está junto a la estantería de la fila 4, columna 3."},{personId:"V",after:["E","B","C","D"],nudge:"Quedan libres las filas 1 y 4, y las columnas 2 y 5. ¿Qué fila le corresponde a Amaia?",reasoning:"La fila 1 es para Amaia, así que Verónica tiene que estar en la fila 4. Allí quedan libres las columnas 2 y 5. En la fila 4, columna 2 hay una estantería, y ahí no puede estar nadie. ¿Qué casilla queda?",answer:"Verónica está en la fila 4, columna 5. La fila 1 es para Amaia, y en la fila 4, columna 2 hay una estantería."},{personId:"A",after:["E","B","C","D","V"],nudge:"Solo falta una persona. ¿Qué dice la tarjeta de Amaia?",reasoning:"Amaia se encontraba en la fila superior, la fila 1. Todas las columnas menos la columna 2 ya están ocupadas. ¿Qué casilla es?",answer:"Amaia está en la fila 1, columna 2. Se encontraba en la fila superior, y la columna 2 es la única columna libre."}],Z="Cristian es el culpable: es el único sospechoso en el tocador, donde se encontró a Verónica.",aa={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ea={source:N,model:W,date:X,steps:Y,murderer:Z,review:aa},na="eee2a5a776d9",la="vertaler + keurder (claude-opus-5-5)",sa="2026-10-20",oa=[{personId:"B",after:[],nudge:"Empieza por Bruno: la columna más a la derecha y una esquina de su estancia. Después fíjate en Enrique, que se encontraba en una fila más baja que la de Bruno.",reasoning:"La columna más a la derecha pertenece entera al invernadero. Las esquinas del invernadero en la columna 6 están en las filas 1 y 6. Enrique se encontraba en una fila más baja que la de Bruno. Si Bruno estuviera en la fila 6, la de más abajo, nadie podría estar en una fila más baja que la suya. ¿Qué esquina queda entonces?",answer:"Bruno está en la fila 1, columna 6. En la columna 6, el invernadero tiene esquinas en las filas 1 y 6, y con Bruno en la fila 6 Enrique no podría estar en una fila más baja que la suya."},{personId:"C",after:["B"],nudge:"César estaba en la 4.ª columna. Mira la fila 6: ¿quién puede estar todavía allí? Piensa en Enrique y su cama.",reasoning:"Enrique se encontraba en una cama. Las camas están en las columnas 3 y 4, pero la columna 4 es para César, así que Enrique está en la columna 3, en la fila 3 o 4. En la fila 6 hay mesas en las columnas 1 y 2 y una planta en la columna 5, y la columna 6 está ocupada. La columna 3 es para Enrique, que no puede estar en la fila 6. ¿Quién puede ocupar entonces la casilla de la fila 6?",answer:"César está en la fila 6, columna 4. En la fila 6 solo quedan las columnas 3 y 4; la columna 3 es para Enrique, en la cama de la fila 3 o 4, así que la fila 6 es para César."},{personId:"E",after:["B","C"],nudge:"Enrique estaba en la cama de la columna 3, en la fila 3 o 4. Mira la tarjeta de Antonio: ¿en qué esquina puede estar?",reasoning:"Antonio se encontraba en una esquina de su estancia, y en su estancia también había alguien con gafas. Para él quedan descartadas las columnas 3, 4 y 6 y las filas 1 y 6. Quedan entonces estas esquinas: la fila 2, columna 1, en la biblioteca, y la fila 3, columnas 1 y 2, en la habitación de invitados. En la biblioteca no cabe nadie más con él, porque la fila 1 está ocupada y en la fila 2, columna 2 hay una estantería. Así que Antonio está en la fila 3. ¿Qué fila le toca entonces a Enrique?",answer:"Enrique está en la fila 4, columna 3. Tiene que estar en la cama de la columna 3; la fila 3 es para Antonio, porque solo en una esquina de la habitación de invitados, en la fila 3, puede tener a alguien con gafas en su estancia."},{personId:"V",after:["B","C","E"],nudge:"Antonio estaba en la fila 3 de la habitación de invitados, con alguien más con gafas. ¿Quién es, y qué fila y qué columna le quedan a Vanesa?",reasoning:"Antonio estaba en la habitación de invitados, en la fila 3, como se vio antes. Enrique también lleva gafas, pero está en el despacho. Así que Daniela estaba con Antonio en la habitación de invitados. Quedan libres las filas 2 y 5; la habitación de invitados ocupa las filas 3 a 6, así que Daniela se queda con la fila 5. Antonio y Daniela ocupan las columnas 1 y 2. ¿Qué fila y qué columna le quedan a Vanesa?",answer:"Vanesa está en la fila 2, columna 5. Daniela tiene que estar con Antonio en la habitación de invitados, en la fila 5, y los dos ocupan las columnas 1 y 2; a Vanesa le quedan la fila 2 y la columna 5."},{personId:"D",after:["B","C","E","V"],nudge:"Daniela estaba en la habitación de invitados, en la fila 5. ¿Qué dice su tarjeta sobre Antonio?",reasoning:"Daniela estaba con Antonio en la habitación de invitados, en la fila 5, como se vio antes. Ella y Antonio ocupan las columnas 1 y 2. Daniela estaba en algún lugar a la izquierda de Antonio. ¿Cuál de las dos columnas está a la izquierda?",answer:"Daniela está en la fila 5, columna 1. Ella y Antonio ocupan las columnas 1 y 2, y Daniela estaba en algún lugar a la izquierda de Antonio."},{personId:"A",after:["B","C","E","V","D"],nudge:"Antonio es el último. ¿Qué fila y qué columna quedan libres?",reasoning:"Todas las filas menos la fila 3 están ocupadas, y todas las columnas menos la columna 2. Esa casilla es una esquina de la habitación de invitados, y Daniela, con sus gafas, está en la misma estancia, como pide la tarjeta de Antonio.",answer:"Antonio está en la fila 3, columna 2. Es la única casilla libre, una esquina de la habitación de invitados, con Daniela en la misma estancia."}],ia="Vanesa yace en el invernadero, y Bruno es el único sospechoso allí. Así que Bruno es el culpable.",ra={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ua={source:na,model:la,date:sa,steps:oa,murderer:ia,review:ra},ta="fa9cb05db2c4",ca="vertaler + keurder (claude-opus-5-5)",da="2026-10-20",ma=[{personId:"F",after:[],nudge:"Empieza por Francisco y David: David estaba exactamente dos filas por debajo de Francisco. ¿En qué filas puede estar David si tienes en cuenta también la tarjeta de Alicia?",reasoning:"En la fila 1, columna 5 hay una estantería, así que Francisco no está en la fila 1 y David (dos filas más abajo) está como mínimo en la fila 4. Alicia estaba en algún lugar por debajo de David y en algún lugar por encima de un hombre, así que Alicia no está en la fila 7, y David no está ni en la fila 6 ni en la 7. En la mitad izquierda (columnas 1 a 3), la fila 4 solo tiene estanterías, así que David está en la fila 5. Francisco estaba dos filas más arriba: ¿qué casilla de la columna 5 es esa?",answer:"Francisco está en la fila 3, columna 5. David tiene que estar en la fila 5: a la izquierda, la fila 4 solo tiene estanterías, y si David estuviera en la fila 6 o 7, Alicia no podría estar por debajo de él y a la vez por encima de un hombre."},{personId:"C",after:["F"],nudge:"César estaba en la 3.ª columna. Mira qué filas ya son de otros: piensa en David, Alicia y Enrique.",reasoning:"David está en la fila 5, como se vio antes. Alicia estaba en algún lugar por debajo de David y en algún lugar por encima de un hombre, así que Alicia está en la fila 6. Enrique se encontraba en la bodega (filas 6 y 7), así que Enrique está en la fila 7. En la columna 3 hay una mesa en la fila 2, una estantería en la fila 4 y un armario en la fila 6, y la fila 3 está ocupada por Francisco. ¿Qué casilla le queda a César?",answer:"César está en la fila 1, columna 3. La fila 3 es de Francisco, la 5 de David, la 6 de Alicia y la 7 de Enrique; en la fila 2 hay una mesa, en la fila 4 una estantería y en la fila 6 un armario."},{personId:"A",after:["F","C"],nudge:"Alicia está en la fila 6. Fíjate en Belén: se encontraba exactamente una columna a la izquierda de Alicia. ¿Qué columnas ya están ocupadas?",reasoning:"Alicia está en la fila 6, como se vio antes. David estaba en la mitad izquierda y la columna 3 está ocupada por César; como Enrique se encontraba en una columna más a la izquierda que la de David, la columna 2 es para David y la columna 1 para Enrique. En la fila 6 hay armarios en las columnas 3 y 5, así que a Alicia le quedan las columnas 4, 6 y 7 de la fila 6. Belén se encontraba exactamente una columna a la izquierda de Alicia, pero la columna 3 está ocupada por César y la columna 5 por Francisco. ¿Qué sitio le queda entonces a Alicia?",answer:"Alicia está en la fila 6, columna 7. Las columnas 1 y 2 son para Enrique y David, en las columnas 3 y 5 hay armarios, y con Alicia en la columna 4 o 6, Belén tendría que estar en la columna 3 (César) o 5 (Francisco)."},{personId:"B",after:["F","C","A"],nudge:"Mira la fila 4. ¿Qué casillas siguen libres ahí y quién puede ir todavía?",reasoning:"Belén se encontraba exactamente una columna a la izquierda de Alicia, así que la columna 6 es para Belén. En la fila 4 hay estanterías en las columnas 1 a 4, la columna 5 está ocupada por Francisco y la columna 7 por Alicia. En la fila 4 solo queda una casilla, y cada fila tiene exactamente una persona. ¿Quién tiene que estar ahí?",answer:"Belén está en la fila 4, columna 6. Por lo demás, la fila 4 solo tiene estanterías y las columnas de Francisco y Alicia, y la columna 6 es para Belén."},{personId:"E",after:["F","C","A","B"],nudge:"Enrique se encontraba en la bodega y en una columna más a la izquierda que la de David. ¿Qué fila y qué columna le quedan?",reasoning:"La bodega ocupa las filas 6 y 7, y la fila 6 está ocupada por Alicia, así que Enrique está en la fila 7. David estaba en la mitad izquierda y la columna 3 está ocupada por César, así que David está en la columna 1 o 2. Enrique se encontraba en una columna más a la izquierda que la de David, así que Enrique tiene que estar en la columna 1. ¿Qué casilla es esa?",answer:"Enrique está en la fila 7, columna 1. La fila 6 es de Alicia, y como Enrique estaba en una columna más a la izquierda que la de David (columna 1 o 2, porque la 3 es de César), solo le queda la columna 1."},{personId:"D",after:["F","C","A","B","E"],nudge:"¿Qué dice la tarjeta de David? Compárala con el sitio de Francisco.",reasoning:"David estaba exactamente dos filas por debajo de Francisco, así que está en la fila 5. Estaba en la mitad izquierda, y ahí la columna 1 está ocupada por Enrique y la columna 3 por César. ¿Qué casilla queda en la fila 5?",answer:"David está en la fila 5, columna 2. Estaba exactamente dos filas por debajo de Francisco, y en la mitad izquierda las columnas 1 (Enrique) y 3 (César) ya están ocupadas."},{personId:"V",after:["F","C","A","B","E","D"],nudge:"Todos los sospechosos están colocados. ¿Qué fila y qué columna siguen completamente vacías?",reasoning:"Cada fila y cada columna tiene exactamente una persona. La fila 2 y la columna 4 son la única fila y la única columna donde todavía no hay nadie. En la casilla donde se cruzan hay un sofá, y ahí se puede estar. Así que Vicente tiene que estar ahí.",answer:"Vicente está en la fila 2, columna 4. Es la única fila y la única columna que siguen vacías."}],fa="Vicente estaba en el despacho. El único sospechoso que estaba allí es Francisco, así que Francisco es el culpable.",pa={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ya={source:ta,model:ca,date:da,steps:ma,murderer:fa,review:pa},ba="e42c954df5cd",qa="vertaler + keurder (claude-opus-5-5)",ga="2026-10-20",va=[{personId:"A",after:[],nudge:"Fija primero las filas de David y Guillermo, y después mira a Bárbara y Cristina. ¿Qué filas les quedan a Amaia y Felipe?",reasoning:"David está en la fila 2 y Guillermo en la fila 3, así que Bárbara (mitad superior) tiene que estar en la fila 1 o 4. Cristina se encontraba en una fila más alta que la de Bárbara, así que Bárbara está en la fila 4 y Cristina en la fila 1. Así, las filas 1 a 4 son para Cristina, David, Guillermo y Bárbara, y Amaia y Felipe tienen que estar en las filas 5 a 8. Ahí, justo al lado de una mesa, Amaia puede estar en la fila 5, columna 7; la fila 5, columna 8; o la fila 6, columna 7 (la fila 7, columna 8 no cuenta: una pared separa esa casilla de la mesa). Felipe estaba en algún lugar por encima de Amaia: ¿en qué fila no puede estar entonces Amaia?",answer:"Amaia está en la fila 6, columna 7. Las filas 1 a 4 son para Cristina, David, Guillermo y Bárbara; justo al lado de una mesa puede estar en la fila 5 o 6, y en la fila 5 Felipe no podría estar por encima de ella."},{personId:"C",after:["A"],nudge:"Cristina está en la fila 1, como se vio con Amaia. Averigua primero en qué estancia está Bárbara y luego lee la tarjeta de Eduardo.",reasoning:"Bárbara está en la fila 4, y alguien más en su estancia era una mujer. En el tocador eso no es posible (Cristina está en la fila 1 y Amaia en la cocina), así que Bárbara está en la cocina, en la columna 4 o más a la derecha. Eduardo se encontraba en una columna más a la derecha que la de una mujer: no la de Cristina, porque estaba en algún lugar a la izquierda de ella, así que la de Bárbara o la de Amaia. Así, Eduardo está en la columna 5 o más a la derecha, y Cristina, todavía más a la derecha. En la fila 1, columna 6 hay una estantería y la columna 7 está ocupada por Amaia: ¿qué columna queda?",answer:"Cristina está en la fila 1, columna 8. Eduardo estaba en una columna más a la derecha que la de Bárbara (cocina, columna 4 o más) o la de Amaia, o sea, en la columna 5 o más, y Cristina aún más a la derecha; en la fila 1, columna 6 hay una estantería y la columna 7 está ocupada."},{personId:"G",after:["A","C"],nudge:"Guillermo está en la fila 3, pero no en el invernadero. ¿Qué casillas de la fila 3 quedan entonces?",reasoning:"Guillermo estaba en la 3.ª fila y no estaba en el invernadero, así que no está en la columna 1, 2 ni 3. En la fila 3 hay una mesa en las columnas 5 y 6, y las columnas 7 y 8 están ocupadas por Amaia y Cristina. ¿Qué casilla sigue libre?",answer:"Guillermo está en la fila 3, columna 4. Las columnas 1 a 3 son el invernadero, en las columnas 5 y 6 de la fila 3 hay una mesa, y las columnas 7 y 8 están ocupadas."},{personId:"B",after:["A","C","G"],nudge:"Bárbara está en la cocina, en la fila 4. Mira qué columnas siguen libres, y piensa en Eduardo.",reasoning:"Bárbara está en la cocina, en la fila 4, como se vio antes. Las columnas 4 y 8 están ocupadas por Guillermo y Cristina, y en la fila 4, columna 7 hay una mesa, así que Bárbara está en la columna 5 o 6. Eduardo estaba en la columna 5 o más a la derecha (ver Cristina) y en algún lugar a la izquierda de Cristina, en la columna 8; la columna 7 está ocupada, así que Eduardo está en la columna 5 o 6. Si Bárbara estuviera en la columna 6, Eduardo tendría que estar en la columna 5, pero entonces no habría ninguna mujer en una columna más a la izquierda que la suya. ¿Qué columna le toca entonces a Bárbara?",answer:"Bárbara está en la fila 4, columna 5. Tiene que estar en la cocina, en la columna 5 o 6, y con ella en la columna 6, Eduardo estaría en la columna 5, sin ninguna mujer en una columna más a la izquierda."},{personId:"E",after:["A","C","G","B"],nudge:"Eduardo tenía que estar en la columna 5 o 6. Bárbara está ahora en la columna 5. ¿Qué filas siguen libres en la columna 6?",reasoning:"Eduardo está en la columna 5 o 6, como se vio antes, y la columna 5 está ocupada por Bárbara. Las filas 1, 3, 4 y 6 ya están ocupadas por Cristina, Guillermo, Bárbara y Amaia, y la fila 2 es para David. Felipe tenía que estar en las filas 5 a 8 y por encima de Amaia (fila 6), así que la fila 5 es para Felipe. En la fila 8, columna 6 hay un armario. ¿Qué casilla de la columna 6 le queda a Eduardo?",answer:"Eduardo está en la fila 7, columna 6. Tiene que estar en la columna 6; las filas 1, 3, 4 y 6 están ocupadas, la fila 2 es para David, la 5 para Felipe (por encima de Amaia) y en la fila 8, columna 6 hay un armario."},{personId:"F",after:["A","C","G","B","E"],nudge:"Felipe está en la fila 5. Lee la segunda frase de su tarjeta.",reasoning:"Felipe está en la fila 5, como se vio antes. Las columnas 4 a 8 están ocupadas, así que siguen libres las columnas 1, 2 y 3. Se encontraba exactamente dos columnas a la derecha de un hombre. Desde la columna 1 o 2 no hay ninguna columna dos posiciones a su izquierda. ¿Qué columna queda?",answer:"Felipe está en la fila 5, columna 3. Las columnas 4 a 8 están ocupadas, y en la columna 1 o 2 no puede haber ningún hombre dos columnas a su izquierda."},{personId:"V",after:["A","C","G","B","E","F"],nudge:"¿Dónde yace Venancio? Mira qué filas y columnas siguen libres, y piensa en la tarjeta de David.",reasoning:"Siguen libres las filas 2 y 8, y las columnas 1 y 2. David estaba en la 2.ª fila, así que Venancio tiene que estar en la fila 8. En la fila 8, columna 1 hay una planta. ¿En qué casilla está entonces Venancio?",answer:"Venancio está en la fila 8, columna 2. La fila 2 es para David, y en la fila 8, columna 1 hay una planta."},{personId:"D",after:["A","C","G","B","E","F","V"],nudge:"¿Qué dice la tarjeta de David?",reasoning:"David estaba en la 2.ª fila. ¿Qué columna sigue libre ahí?",answer:"David está en la fila 2, columna 1. La fila 2 es la suya, y la columna 1 es la única columna libre."}],Aa="Venancio yace en el tocador, y Felipe es el único sospechoso en esa estancia: David está en el invernadero, Cristina y Guillermo en el dormitorio, Bárbara y Amaia en la cocina, y Eduardo en la habitación de invitados. Así que Felipe es el culpable.",Ea={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ha={source:ba,model:qa,date:ga,steps:va,murderer:Aa,review:Ea},Ca="fd37cde9aa3a",Ba="vertaler + keurder (claude-opus-5-5)",Da="2026-10-20",ja=[{personId:"B",after:[],nudge:"Mira las columnas 1 y 2: ¿en qué estancias están, y quién no puede estar ahí de ninguna manera según su tarjeta?",reasoning:"Las columnas 1 y 2 están en el tocador y el dormitorio, y en los dos hay una silla. En las estancias de Fernando y de Diego no había ninguna silla, así que ellos no están ahí; Diego estaba en la misma estancia que Carolina, así que Carolina tampoco. Ana estaba en algún lugar a la derecha de Carolina, y Elena, exactamente cuatro columnas a la derecha de ella, así que esas dos tampoco. Las columnas 1 y 2 son, pues, para Bruno y Victoria. Bruno estaba en la 5.ª fila y no estaba junto a ningún sofá: en la fila 5, columna 2 estaría junto al sofá de las filas 4 y 5, columna 1. Quien está sobre el propio sofá no está junto a él. ¿Dónde está entonces Bruno?",answer:"Bruno está en la fila 5, columna 1. Las columnas 1 y 2 son solo para Bruno y Victoria (las dos estancias tienen una silla), y en la fila 5, columna 2, Bruno estaría junto a un sofá."},{personId:"V",after:["B"],nudge:"Mira la fila 7: ahí tiene que haber alguien. Piensa primero en qué columna puede estar Carolina.",reasoning:"En la fila 7 hay una mesa en las columnas 5, 6 y 7, y la columna 1 está ocupada. Carolina estaba exactamente cuatro columnas a la izquierda de Elena, o sea, en la columna 1, 2 o 3, y en una estancia sin silla (la de Diego): eso solo es posible en la cocina, en la columna 3. Diego también está en la cocina, y como la columna 3 es para Carolina, la columna 4 es para Diego. Así que las columnas 3 y 4 de la fila 7 quedan descartadas. La columna 2 es para Victoria, como se vio antes. ¿Qué casilla de la fila 7 queda?",answer:"Victoria está en la fila 7, columna 2. En la fila 7 tiene que haber alguien: la columna 1 está ocupada, en las columnas 5 a 7 hay una mesa, y las columnas 3 y 4 son para Carolina y Diego, en la cocina."},{personId:"E",after:["B","V"],nudge:"Carolina está en la columna 3. ¿Dónde está entonces Elena, y qué hombre puede estar exactamente cuatro filas por debajo de ella?",reasoning:"Carolina está en la columna 3, así que Elena está exactamente cuatro columnas más a la derecha, en la columna 7. Elena se encontraba exactamente cuatro filas por encima de un hombre, así que está en la fila 1, 2 o 3. En la fila 7 está Victoria, una mujer, así que la fila 3 queda descartada. En la fila 6 no puede haber ningún hombre: Diego está en la cocina, en la estancia de Fernando no había ninguna silla, y en el dormitorio hay una silla. Así que la fila 2 también queda descartada. ¿Qué hombre está en la fila 5?",answer:"Elena está en la fila 1, columna 7. Tiene que estar en la columna 7 (exactamente cuatro columnas a la derecha de Carolina) y exactamente cuatro filas por encima de un hombre: es Bruno, en la fila 5; en la fila 6 no puede haber ningún hombre y en la fila 7 está Victoria."},{personId:"A",after:["B","V","E"],nudge:"Mira la columna 6: ¿qué casillas siguen libres ahí, y quién puede estar en esa estancia?",reasoning:"En la columna 6 tiene que haber alguien. Ahí hay un piano en las filas 2 y 3, un armario en la fila 4 y una mesa en la fila 7; las filas 1 y 5 están ocupadas. Solo queda la fila 6, columna 6, en el dormitorio, donde hay una silla. Carolina y Diego están en la cocina, y en la estancia de Fernando no había ninguna silla. ¿Quién queda entonces para esta casilla?",answer:"Ana está en la fila 6, columna 6. Es la única casilla libre de la columna 6 (el piano, el armario y la mesa bloquean el resto), y Carolina, Diego y Fernando no pueden estar en el dormitorio, que tiene una silla."},{personId:"F",after:["B","V","E","A"],nudge:"¿Qué columna le queda a Fernando? Después mira la tarjeta de Carolina: exactamente tres filas por debajo de ella tiene que haber un hombre.",reasoning:"Las columnas 3 y 4 son para Carolina y Diego, como se vio antes, así que Fernando tiene que estar en la columna 5. Ahí las filas 1, 5 y 6 están ocupadas y en la fila 7 hay una mesa, así que le quedan las filas 2, 3 y 4. Carolina estaba exactamente tres filas por encima de un hombre; la fila 1 está ocupada y desde la fila 3, tres filas más abajo estaría Ana, así que Carolina está en la fila 2. Diego está entonces en la cocina, en la fila 3. ¿Qué fila le queda a Fernando?",answer:"Fernando está en la fila 4, columna 5. Tiene que estar en la columna 5; la fila 2 es para Carolina (desde la fila 3, Ana estaría tres filas por debajo de ella) y la fila 3 para Diego, en la cocina."},{personId:"C",after:["B","V","E","A","F"],nudge:"Carolina está en la columna 3 de la cocina. ¿Quién está tres filas por debajo de cada fila que todavía tiene libre?",reasoning:"Carolina está en la cocina, en la columna 3, o sea, en la fila 1, 2 o 3. La fila 1 está ocupada. Carolina estaba exactamente tres filas por encima de un hombre. Tres filas por debajo de la fila 3 está Ana, una mujer. ¿Quién está tres filas por debajo de la fila 2?",answer:"Carolina está en la fila 2, columna 3. La fila 1 está ocupada y desde la fila 3, tres filas más abajo estaría Ana, una mujer; tres filas por debajo de la fila 2 está Bruno."},{personId:"D",after:["B","V","E","A","F","C"],nudge:"Diego es el último. ¿Qué dice su tarjeta, y qué fila y qué columna siguen vacías?",reasoning:"Diego estaba en la misma estancia que Carolina, o sea, en la cocina. Todas las demás personas ya están colocadas, así que a él le toca la única fila y la única columna que siguen libres. ¿Está esa casilla en la cocina?",answer:"Diego está en la fila 3, columna 4: la única fila y la única columna libres, y esa casilla está en la cocina, con Carolina."}],La="Victoria yace en el dormitorio, y Ana es la única sospechosa en esa estancia. Así que Ana es la culpable.",Qa={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},wa={source:Ca,model:Ba,date:Da,steps:ja,murderer:La,review:Qa},Va="c895d9aa52fd",Fa="vertaler + keurder (claude-opus-5-5)",za="2026-10-20",Ia=[{personId:"B",after:[],nudge:"Empieza por Bárbara: ¿qué hombre puede estar exactamente tres columnas a su izquierda? Después mira quién puede ocupar las filas 1, 2 y 8.",reasoning:"Gonzalo está en la columna 1 (dos columnas a la izquierda de la columna 3 de Alberto). Bárbara estaba exactamente tres columnas a la derecha de un hombre: desde Alberto sería la columna 6 (de Carlos), desde Carlos la 9 (no existe), así que desde Gonzalo: la columna 4. ¿Quién puede ocupar las filas 1, 2 u 8? Débora no (fila 4). Alberto y Fernanda tampoco: Fernanda se encontraba exactamente una fila por debajo de Alberto, en la mitad inferior; en la fila 4, columna 3 hay una estantería y la fila 7, columna 3 está fuera, así que Alberto está en la fila 5 o 6, y Fernanda en la 6 o 7. Carlos no: en la columna 6, las filas 1 y 2 están fuera y en la fila 8 hay una planta. Gonzalo tampoco: en la fila 1, columna 1 hay un armario, la fila 8 está fuera, y desde la fila 2 tendría que haber un hombre en la fila 4, la de Débora. Así que esas tres filas son para Bárbara, Eva y Valeria. ¿Cuál es una esquina para Bárbara en la columna 4?",answer:"Bárbara está en la fila 1, columna 4: exactamente tres columnas a la derecha de Gonzalo. Solo ella, Eva y Valeria pueden ocupar las filas 1, 2 y 8; la fila 2, columna 4 no es una esquina y la fila 8, columna 4 está fuera de la casa."},{personId:"E",after:["B"],nudge:"Las filas 1, 2 y 8 son para Bárbara, Eva y Valeria. ¿Puede Eva estar en la fila inferior, si estaba en algún lugar por encima de un hombre?",reasoning:"Como vimos con Bárbara, las filas 1, 2 y 8 son para Bárbara, Eva y Valeria, y Bárbara está en la fila 1. Eva estaba en algún lugar por encima de un hombre, así que no en la fila 8: va a la fila 2. La columna 1 es para Gonzalo, la 3 para Alberto, la 4 está ocupada por Bárbara, y en la fila 2 las columnas 6 a 8 están fuera de la casa. La fila 2, columna 5 está en la habitación de invitados, igual que Bárbara, y Eva no estaba en la misma estancia que Bárbara. ¿Qué casilla queda en la fila 2?",answer:"Eva está en la fila 2, columna 2. Tenía que estar en la fila 2 (por encima de un hombre, así que no en la fila 8); la columna 1 es para Gonzalo, la 3 para Alberto, la 4 está ocupada, la 5 está en la estancia de Bárbara y las columnas 6 a 8 están fuera de la casa."},{personId:"D",after:["B","E"],nudge:"Débora se encontraba en la 4.ª fila y en una columna más a la izquierda que la de Carlos. ¿Qué columnas siguen libres en esa fila?",reasoning:"Débora se encontraba en la 4.ª fila. Las columnas 2 y 4 están ocupadas por Eva y Bárbara, la 1 es para Gonzalo y la 6 para Carlos. En la fila 4, columna 3 hay una estantería y en la fila 4, columna 8 un baúl. La fila 4, columna 7 queda descartada, porque Débora se encontraba en una columna más a la izquierda que la de Carlos, que está en la columna 6. ¿Qué queda?",answer:"Débora está en la fila 4, columna 5. Las columnas 1, 2, 4 y 6 son para otros, en las columnas 3 y 8 hay una estantería y un baúl, y la columna 7 no está a la izquierda de Carlos."},{personId:"V",after:["B","E","D"],nudge:"¿Qué fila le queda a Valeria? Después mira las columnas 7 y 8 y a Fernanda.",reasoning:"Las filas 1, 2 y 8 eran para Bárbara, Eva y Valeria, como vimos con Bárbara, así que Valeria va a la fila 8. Las columnas 7 y 8 quedan para Fernanda y Valeria, porque Gonzalo, Alberto y Carlos tienen cada uno su propia columna. En la columna 3, Alberto solo puede estar en la fila 5 o 6: en la fila 4, columna 3 hay una estantería, la fila 7 está fuera de la casa, y Fernanda tenía que estar exactamente una fila más abajo, en la mitad inferior. Así que Fernanda estaba en la fila 6 o 7, y en esas filas la columna 8 tiene armarios. Por tanto, la columna 7 es para Fernanda. ¿Qué casilla de la fila 8 le queda a Valeria?",answer:"Valeria está en la fila 8, columna 8. La fila 8 era para ella, las columnas 1 a 4 están fuera de la casa, la 5 está ocupada por Débora, en la fila 8, columna 6 hay una planta y la columna 7 es para Fernanda."},{personId:"C",after:["B","E","D","V"],nudge:"Carlos se encontraba en la 6.ª columna, en una estancia sin mujeres. ¿En qué estancias de la columna 6 ya hay una mujer?",reasoning:"En la estancia de Carlos no había ninguna mujer. En la columna 6, las filas 1 y 2 están fuera de la casa, y en la fila 8, columna 6 hay una planta. La fila 3, columna 6 está en la habitación de invitados, donde está Bárbara. Las filas 4 a 6 de la columna 6 pertenecen al invernadero, donde está Débora. ¿Qué casilla queda?",answer:"Carlos está en la fila 7, columna 6. Las filas 1 y 2 están fuera de la casa, en la fila 8 hay una planta, y en la habitación de invitados está Bárbara y en el invernadero Débora, las dos mujeres."},{personId:"F",after:["B","E","D","V","C"],nudge:"Fernanda va en la columna 7, como vimos con Valeria. ¿Qué filas de la mitad inferior siguen libres allí?",reasoning:"La columna 7 es para Fernanda, como vimos con Valeria. Siguen libres las filas 3, 5 y 6; Fernanda estaba en la mitad inferior, así que en la fila 5 o 6. En la fila 5, Alberto estaría exactamente una fila más arriba, en la fila 4, pero esa fila es de Débora. ¿Dónde va Fernanda?",answer:"Fernanda está en la fila 6, columna 7. En la columna 7 solo están libres las filas 3, 5 y 6; la fila 3 no está en la mitad inferior y en la fila 5 Alberto tendría que estar en la fila 4, la de Débora."},{personId:"A",after:["B","E","D","V","C","F"],nudge:"Fernanda ya está en el tablero. ¿Qué dice su tarjeta sobre Alberto?",reasoning:"Fernanda se encontraba exactamente una fila por debajo de Alberto, y Fernanda está en la fila 6. La propia tarjeta de Alberto dice que estaba en la 3.ª columna. ¿Adónde llegas entonces?",answer:"Alberto está en la fila 5, columna 3. Estaba en la 3.ª columna y exactamente una fila por encima de Fernanda, que está en la fila 6."},{personId:"G",after:["B","E","D","V","C","F","A"],nudge:"Gonzalo es el último que aún no está en el tablero. ¿Qué dice su tarjeta?",reasoning:"La fila 3 y la columna 1 son la única fila y la única columna que siguen libres. Allí Gonzalo está exactamente dos columnas a la izquierda de Alberto y exactamente dos filas por encima de él, tal como dice su tarjeta.",answer:"Gonzalo está en la fila 3, columna 1. Es la última fila y la última columna libres: exactamente dos columnas a la izquierda de Alberto y exactamente dos filas por encima de él."}],$a="Valeria yace en la bodega. Fernanda era la única sospechosa en la bodega; Carlos está en el dormitorio, Débora en el invernadero, Alberto en la cocina, y Bárbara, Eva y Gonzalo en la habitación de invitados y el despacho. Así que Fernanda es la culpable.",_a={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},xa={source:Va,model:Fa,date:za,steps:Ia,murderer:$a,review:_a},Ga="e82e6e33b7b4",Sa="vertaler + keurder (claude-opus-5-5)",ka="2026-10-26",Ma=[{personId:"A",after:[],nudge:"Empieza por Aitana. Su tarjeta menciona la fila inferior: ¿qué casillas de esa fila quedan dentro de la casa?",reasoning:"Aitana se encontraba en la fila inferior, la fila 8. En la fila 8, las casillas de las columnas 1 a 4, 7 y 8 quedan fuera de la casa. En la fila 8, columna 6 hay una planta, y allí no puede estar nadie. ¿Qué casilla de la fila 8 queda entonces?",answer:"Aitana está en la fila 8, columna 5. En la fila 8, las casillas de las columnas 1 a 4, 7 y 8 quedan fuera de la casa, y en la fila 8, columna 6 hay una planta."},{personId:"V",after:["A"],nudge:"Aitana está en el tocador, y su tarjeta dice que allí había otra mujer. ¿Qué mujer puede ser, y dónde?",reasoning:"Según la tarjeta de Aitana, había otra mujer en el tocador. En el tocador, la columna 5 está ocupada por Aitana y en la fila 8, columna 6 hay una planta; solo la casilla de la fila 7, columna 6 sigue libre. Las mujeres son Dorotea, Elena y Viviana. Dorotea no estaba en la misma estancia que Aitana, y Elena se encontraba en la 2.ª columna. ¿Quién tiene que estar entonces en esa casilla libre?",answer:"Viviana yace en la fila 7, columna 6. Es la única casilla libre del tocador, y Dorotea (no estaba en la misma estancia que Aitana) y Elena (en la 2.ª columna) no pueden estar allí."},{personId:"G",after:["A","V"],nudge:"Mira a Gustavo: se encontraba ante una ventana. Repasa las ventanas y ten presentes a Cristian, Elena y Fernando.",reasoning:"La fila 5 es para Cristian (exactamente tres filas por encima de Aitana) y la columna 2 para Elena (en la 2.ª columna). Las casillas ante una ventana son: fila 1, columnas 1 y 2; fila 2, columna 8; fila 5, columna 8; fila 6, columna 1 (en la fila 3, columna 8 hay una planta; la fila 8, columna 5 está ocupada por Aitana). Se descartan las de la fila 1, columna 2 (Elena) y de la fila 5, columna 8 (Cristian). Gustavo se encontraba exactamente una fila por encima de Fernando, y Fernando en una columna más a la izquierda que la de Aitana, o sea, en las columnas 1 a 4. Si Gustavo estuviera en la fila 6, columna 1, Fernando estaría en la fila 7, pero allí yace Viviana. Si estuviera en la fila 1, columna 1, Fernando estaría en la fila 2: en la fila 2, columna 1 hay una planta, la columna 2 es para Elena, en la fila 2, columna 3 está el armario y la casilla de la fila 2, columna 4 está junto a ese armario (Fernando no estaba junto a ningún armario). ¿Qué casilla ante una ventana queda?",answer:"Gustavo está en la fila 2, columna 8. Se descartan las casillas de la fila 1, columna 1 (Fernando no cabría en la fila 2 en una columna más a la izquierda que la de Aitana: planta, columna de Elena, armario, junto al armario), de la fila 6, columna 1 (Viviana yace en la fila 7), de la fila 1, columna 2 (Elena) y de la fila 5, columna 8 (Cristian)."},{personId:"C",after:["A","V","G"],nudge:"Cristian se encontraba exactamente tres filas por encima de Aitana. ¿Qué fila es esa, y en qué columnas hay una planta?",reasoning:"Aitana está en la fila 8, así que Cristian tiene que estar en la fila 5. Hay una planta en la fila 2, columna 1, otra en la fila 8, columna 6 y otra en la fila 3, columna 8. La columna 6 está ocupada por Viviana y la columna 8 por Gustavo. ¿Qué casilla de la fila 5 queda entonces?",answer:"Cristian está en la fila 5, columna 1. Tiene que estar en la fila 5 (exactamente tres filas por encima de Aitana), y de las columnas con planta, la 6 (Viviana) y la 8 (Gustavo) ya están ocupadas."},{personId:"F",after:["A","V","G","C"],nudge:"Gustavo se encontraba exactamente una fila por encima de Fernando, y Fernando en una columna más a la izquierda que la de Aitana. ¿Qué fila y qué columnas son esas?",reasoning:"Gustavo está en la fila 2, y se encontraba exactamente una fila por encima de Fernando, así que Fernando tiene que estar en la fila 3. Una columna más a la izquierda que la de Aitana significa las columnas 1 a 4. La columna 1 está ocupada por Cristian, la columna 2 es para Elena y en la fila 3, columna 3 hay un baúl. ¿Qué casilla queda?",answer:"Fernando está en la fila 3, columna 4. Tiene que estar en la fila 3 (Gustavo estaba exactamente una fila por encima de él) y en una columna más a la izquierda que la de Aitana; la columna 1 (Cristian), la columna 2 (Elena) y la columna 3 (baúl) quedan descartadas."},{personId:"E",after:["A","V","G","C","F"],nudge:"Elena se encontraba en la 2.ª columna, y en su estancia no había ningún hombre. ¿Qué filas siguen libres?",reasoning:"En la columna 2 siguen libres la fila 1, la fila 4 y la fila 6. La casilla de la fila 4, columna 2 está en el dormitorio, donde está Fernando (un hombre). La casilla de la fila 6, columna 2 está en el pasillo, donde está Cristian (un hombre). ¿Qué casilla queda?",answer:"Elena está en la fila 1, columna 2. La fila 4 queda descartada (Fernando en el dormitorio) y la fila 6 también (Cristian en el pasillo); en el comedor no hay ningún hombre."},{personId:"B",after:["A","V","G","C","F","E"],nudge:"Benito era el único hombre de su estancia. Mira qué filas y columnas siguen libres.",reasoning:"Siguen libres las filas 4 y 6, y las columnas 3 y 7. En la fila 4, columna 7 está la mesa. La casilla de la fila 4, columna 3 está en el dormitorio con Fernando, y la de la fila 6, columna 3, en el pasillo con Cristian; allí Benito no sería el único hombre. ¿Qué casilla queda?",answer:"Benito está en la fila 6, columna 7. En la fila 4, columna 7 hay una mesa, y en la fila 4, columna 3 (Fernando) y la fila 6, columna 3 (Cristian) no sería el único hombre."},{personId:"D",after:["A","V","G","C","F","E","B"],nudge:"Dorotea es la última que todavía no está en el tablero. ¿Qué fila y qué columna siguen libres?",reasoning:"Cada fila y cada columna contiene exactamente una persona. La fila 4 y la columna 3 son las últimas sin nadie. La casilla donde se cruzan está en el dormitorio, no en el tocador, donde está Aitana, así que encaja con la tarjeta de Dorotea.",answer:"Dorotea está en la fila 4, columna 3. La fila 4 y la columna 3 son las últimas libres, y la casilla donde se cruzan está en el dormitorio, no en la estancia de Aitana."}],Ta="Viviana yace en el tocador, y allí Aitana es la única sospechosa: Aitana es la culpable. Cristian está en el pasillo, Fernando y Dorotea en el dormitorio, Elena en el comedor, Gustavo en la biblioteca y Benito en la cocina.",Pa={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-26"},Ha={source:Ga,model:Sa,date:ka,steps:Ma,murderer:Ta,review:Pa},Ja=Object.assign({"/.demo/puzzles/i18n/es/L1-00037ru.json":i,"/.demo/puzzles/i18n/es/L1-00037sm.json":f,"/.demo/puzzles/i18n/es/L1-00037ss.json":A,"/.demo/puzzles/i18n/es/L2-000255s.json":L,"/.demo/puzzles/i18n/es/L2-000255v.json":$,"/.demo/puzzles/i18n/es/L2-000256n.json":T,"/.demo/puzzles/i18n/es/L3-0001qi0.json":K,"/.demo/puzzles/i18n/es/L3-0002cvm.json":ea,"/.demo/puzzles/i18n/es/L3-0002cvz.json":ua,"/.demo/puzzles/i18n/es/L4-0002klf.json":ya,"/.demo/puzzles/i18n/es/L4-0002klr.json":ha,"/.demo/puzzles/i18n/es/L4-0002km3.json":wa,"/.demo/puzzles/i18n/es/L5-0002sbj.json":xa,"/.demo/puzzles/i18n/es/L5-005oou4.json":Ha});export{Ja as default};
